func SealRVX(masterKey string,plain []byte)(RVXEnvelope,error){if len(masterKey)<32{return RVXEnvelope{},errors.New("external key must be 32+ bytes")};key:=sha256.Sum256([]byte(masterKey));block,e:=aes.NewCipher(key[:]);if e!=nil{return RVXEnvelope{},e};g,e:=cipher.NewGCM(block);if e!=nil{return RVXEnvelope{},e};nonce:=make([]byte,g.NonceSize());if _,e=io.ReadFull(rand.Reader,nonce);e!=nil{return RVXEnvelope{},e};ciphertext:=g.Seal(nil,nonce,plain,[]byte("rvx-aead-v1"));return RVXEnvelope{"rvx-aead-v1",base64.RawStdEncoding.EncodeToString(nonce),base64.RawStdEncoding.EncodeToString(ciphertext)},nil}
func OpenRVX(masterKey string,box RVXEnvelope)([]byte,error){if box.Version!="rvx-aead-v1"||len(masterKey)<32{return nil,errors.New("invalid envelope or key")};key:=sha256.Sum256([]byte(masterKey));block,e:=aes.NewCipher(key[:]);if e!=nil{return nil,e};g,e:=cipher.NewGCM(block);if e!=nil{return nil,e};nonce,e:=base64.RawStdEncoding.DecodeString(box.Nonce);if e!=nil||len(nonce)!=g.NonceSize(){return nil,errors.New("invalid nonce")};ciphertext,e:=base64.RawStdEncoding.DecodeString(box.Ciphertext);if e!=nil{return nil,e};return g.Open(nil,nonce,ciphertext,[]byte("rvx-aead-v1"))}
